  1564  static int initialize_context_decompression(blosc2_context* context, const void* src, int32_t srcsize,
  1565                                              void* dest, int32_t destsize) {
  1566    int32_t cbytes;
  1567    int32_t bstarts_offset;
  1568    int32_t bstarts_end;
  1569
  1570    context->do_compress = 0;
  1571    context->src = (const uint8_t*)src;
  1572    context->srcsize = srcsize;
  1573    context->dest = (uint8_t*)dest;
  1574    context->destsize = destsize;
  1575    context->output_bytes = 0;
  1576    context->end_threads = 0;
  1577
  1578    if (context->srcsize < BLOSC_MIN_HEADER_LENGTH) {
  1579      /* Not enough input to read minimum header */
  1580      return -1;
  1581    }
  1582
  1583    context->header_flags = context->src[BLOSC2_CHUNK_FLAGS];
  1584    context->typesize = context->src[BLOSC2_CHUNK_TYPESIZE];
  1585    context->sourcesize = sw32_(context->src + BLOSC2_CHUNK_NBYTES);
  1586    context->blocksize = sw32_(context->src + BLOSC2_CHUNK_BLOCKSIZE);
  1587    cbytes = sw32_(context->src + BLOSC2_CHUNK_CBYTES);
  1588
  1589    // Some checks for malformed headers
  1590    if (context->blocksize <= 0 || context->blocksize > destsize ||
  1591        context->typesize <= 0 || context->typesize > BLOSC_MAX_TYPESIZE ||
  1592        cbytes > srcsize) {
  1593      return -1;
  1594    }
  1595    /* Check that we have enough space to decompress */
  1596    if (context->sourcesize > (int32_t)destsize) {
  1597      return -1;
  1598    }
  1599
  1600    /* Total blocks */
  1601    context->nblocks = context->sourcesize / context->blocksize;
  1602    context->leftover = context->sourcesize % context->blocksize;
  1603    context->nblocks = (context->leftover > 0) ?
  1604                        context->nblocks + 1 : context->nblocks;
  1605
  1606    if (context->block_maskout != NULL && context->block_maskout_nitems != context->nblocks) {
  1607      BLOSC_TRACE_ERROR("The number of items in block_maskout (%d) must match the number"
  1608                        " of blocks in chunk (%d).",
  1609                        context->block_maskout_nitems, context->nblocks);
  1610      return -2;
  1611    }
  1612
  1613    if ((context->header_flags & BLOSC_DOSHUFFLE) &&
  1614        (context->header_flags & BLOSC_DOBITSHUFFLE)) {
  1615      /* Extended header */
  1616      if (context->srcsize < BLOSC_EXTENDED_HEADER_LENGTH) {
  1617        /* Not enough input to read extended header */
  1618        return -1;
  1619      }
  1620      uint8_t* filters = (uint8_t*)(context->src + BLOSC_MIN_HEADER_LENGTH);
  1621      uint8_t* filters_meta = filters + 8;
  1622      uint8_t header_version = context->src[BLOSC2_CHUNK_VERSION];
  1623      // The number of filters depends on the version of the header
  1624      // (we need to read less because filters where not initialized to zero in blosc2 alpha series)
  1625      int max_filters = (header_version == BLOSC2_VERSION_FORMAT_ALPHA) ? 5 : BLOSC2_MAX_FILTERS;
  1626      for (int i = 0; i < max_filters; i++) {
  1627        context->filters[i] = filters[i];
  1628        context->filters_meta[i] = filters_meta[i];
  1629      }
  1630      context->filter_flags = filters_to_flags(filters);
  1631      context->blosc2_flags = context->src[BLOSC2_CHUNK_BLOSC2_FLAGS];
  1632      bstarts_offset = BLOSC_EXTENDED_HEADER_LENGTH;
  1633    } else {
  1634      /* Regular (Blosc1) header */
  1635      context->filter_flags = get_filter_flags(context->header_flags,
  1636                                               context->typesize);
  1637      flags_to_filters(context->header_flags, context->filters);
  1638      bstarts_offset = BLOSC_MIN_HEADER_LENGTH;
  1639    }
  1640
  1641    context->bstarts = (int32_t*)(context->src + bstarts_offset);
  1642    bstarts_end = bstarts_offset + (context->nblocks * sizeof(int32_t));
  1643    if (srcsize < bstarts_end) {
  1644      /* Not enough input to read entire `bstarts` section */
  1645      return -1;
  1646    }
  1647    srcsize -= bstarts_end;
  1648
  1649    /* Read optional dictionary if flag set */
  1650    if (context->blosc2_flags & BLOSC2_USEDICT) {
  1651  #if defined(HAVE_ZSTD)
  1652      context->use_dict = 1;
  1653      if (context->dict_ddict != NULL) {
  1654        // Free the existing dictionary (probably from another chunk)
  1655        ZSTD_freeDDict(context->dict_ddict);
  1656      }
  1657      // The trained dictionary is after the bstarts block
  1658      if (srcsize < sizeof(int32_t)) {
  1659        /* Not enough input to size of dictionary */
  1660        return -1;
  1661      }
  1662      srcsize -= sizeof(int32_t);
  1663      context->dict_size = (size_t)sw32_(context->src + bstarts_end);
  1664      if (context->dict_size <= 0 || context->dict_size > BLOSC2_MAXDICTSIZE) {
  1665        /* Dictionary size is smaller than minimum or larger than maximum allowed */
  1666        return -1;
  1667      }
  1668      if (srcsize < (int32_t)context->dict_size) {
  1669        /* Not enough input to read entire dictionary */
  1670        return -1;
  1671      }
  1672      srcsize -= context->dict_size;
  1673      context->dict_buffer = (void*)(context->src + bstarts_end + sizeof(int32_t));
  1674      context->dict_ddict = ZSTD_createDDict(context->dict_buffer, context->dict_size);
  1675  #endif   // HAVE_ZSTD
  1676    }
  1677
  1678
  1679    return 0;
  1680  }
