  1683  static int write_compression_header(blosc2_context* context,
  1684                                      bool extended_header) {
  1685    int32_t compformat;
  1686    int dont_split;
  1687    int dict_training = context->use_dict && (context->dict_cdict == NULL);
  1688
  1689    // Set the whole header to zeros so that the reserved values are zeroed
  1690    if (extended_header) {
  1990      cbytes = blosc_compress_context(context);
  1991
  1992      // Invalidate the dictionary for compressing other chunks using the same context
  1993      context->dict_buffer = NULL;
  1994      ZSTD_freeCDict(context->dict_cdict);
  1995      context->dict_cdict = NULL;
  1996  #endif  // HAVE_ZSTD
  1997    }
  1998
  1999    return cbytes;
  2000  }
