  2003  void build_filters(const int doshuffle, const int delta,
  2004                     const size_t typesize, uint8_t* filters) {
  2005
  2006    /* Fill the end part of the filter pipeline */
  2007    if ((doshuffle == BLOSC_SHUFFLE) && (typesize > 1))
  2008      filters[BLOSC2_MAX_FILTERS - 1] = BLOSC_SHUFFLE;
  2009    if (doshuffle == BLOSC_BITSHUFFLE)
  2010      filters[BLOSC2_MAX_FILTERS - 1] = BLOSC_BITSHUFFLE;
  2011    if (delta)
  2012      filters[BLOSC2_MAX_FILTERS - 2] = BLOSC_DELTA;
  2013  }
